do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'bib-101';
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 24, $j$6.4 Between the Testaments and the Fullness of Time$j$, $j${"readings": [{"title": "Isaiah 40 (King James Version)", "url": "/portal/bible/Isaiah/40"}, {"title": "Malachi 3 (King James Version)", "url": "/portal/bible/Malachi/3"}, {"title": "Malachi 4 (King James Version)", "url": "/portal/bible/Malachi/4"}, {"title": "Galatians 4 (King James Version)", "url": "/portal/bible/Galatians/4"}], "body": "Read Isaiah 40:1 to 5, Malachi 3:1, Malachi 4:1 to 6 and Galatians 4:1 to 7 in the King James Version. Then read this lesson.\n\nAfter Malachi there were about four hundred years in which no prophet spoke. These years are called the time between the testaments. During that time the Persian Empire gave way to Greece under Alexander the Great, and then Rome ruled the world. Greek became a common language, roads were built, and the Jewish people lived scattered in many cities, each with a synagogue. This prepared the world for the gospel. Galatians 4:4 says that when the fulness of the time was come, God sent forth his Son. Malachi and Isaiah both promised a messenger to prepare the way. In the New Testament this messenger is John the Baptist.\n\nKey words: silence, fullness of time, messenger, preparation, gospel.\n\nYour task: (1) Explain what happened between the testaments. (2) Name the messenger Malachi and Isaiah promised. (3) Write Galatians 4:4 in your own words and tell why the timing mattered.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "We have come to the last lesson in Old Testament Survey. What happens after Malachi? The Old Testament ends, and then there are about four hundred years of silence. No new prophet spoke for God during that time. The Jewish people were waiting.\n\nThose four hundred years were not wasted. God was preparing the world. The Persian Empire, which had let the Jews go home, was conquered by Alexander the Great of Greece. Wherever his armies went, the Greek language spread. Later, Rome took control, and the Romans built roads and kept peace across much of the known world. Jews lived in many cities, and in each place they met in synagogues to read the Scriptures. All of this made it possible for the gospel to spread quickly.\n\nScripture says this in Galatians 4:4, But when the fulness of the time was come, God sent forth his Son, made of a woman, made under the law. God has a perfect timetable. The promises of Genesis, the covenant with David and the words of the prophets came together at exactly the right time.\n\nThe prophets also promised a messenger to prepare the way. Isaiah 40:3 says, The voice of him that crieth in the wilderness, Prepare ye the way of the LORD, make straight in the desert a highway for our God. And Malachi 3:1 says, Behold, I will send my messenger, and he shall prepare the way before me. In the New Testament, John the Baptist appears in the wilderness and fulfills these words. After four hundred years, a prophetic voice was heard again.\n\nThe Old Testament does not end with a finished story. It ends with a promise and an open door. Malachi 4:2 says, But unto you that fear my name shall the Sun of righteousness arise with healing in his wings. Everything we have studied, the creation, the covenant, the Law, the kings, the prophets and the promises, was pointing toward the Savior, Jesus Christ.\n\nYour task is to explain what happened between the testaments, name the messenger Malachi and Isaiah promised, and write Galatians 4:4 in your own words. Then take the four question check and the Unit 6 quiz. After that you will be ready for the Final Assessment and the Final Exam.\n\nYou have read the whole story, and now you are ready for the Savior it promises. Excellence, Faith, Purpose. Thank you for studying the Old Testament with me."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.4 Between the Testaments and the Fullness of Time$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 6, $j$Assessment 6: The Promise Fulfilled$j$, $j${"prompt": "Choose one Old Testament prophecy about the Messiah from this unit: Genesis 3:15, Isaiah 7:14, Isaiah 53, Micah 5:2, Psalm 22 or Zechariah 9:9. Write one paragraph of 150 to 200 words. Quote the prophecy from the King James Version, explain what it promised, and tell how the New Testament shows that Jesus Christ fulfilled it. Then say what that fulfillment means for a student today.", "rubric": "Total 100. Accurate prophecy quoted from the King James Version: 25. Explains what the prophecy promised: 25. Shows how Jesus Christ fulfilled it: 25. Clear writing and correct conventions: 25."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 6: The Promise Fulfilled$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 6, $j$Discussion 6: The Whole Story$j$, $j${"prompt": "After reading the Old Testament from Genesis to Malachi, what part of the story spoke to you most? Name the book or passage, say what it taught you about God, and tell how it could change the way you live. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 6: The Whole Story$j$);
end
$seed$;
